class Solution { public:string largestPalindromic(string num){int count[10]={};for(char ch:num)++count[ch-'0'];string left;for(int digit=9;digit>=0;--digit){int pairs=count[digit]/2;if(digit==0&&left.empty())continue;left+=string(pairs,'0'+digit);count[digit]-=pairs*2;}char center=0;for(int digit=9;digit>=0;--digit)if(count[digit]){center='0'+digit;break;}string answer=left;if(center)answer+=center;answer+=string(left.rbegin(),left.rend());return answer.empty()?"0":answer;} };
